import java.util.EnumMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;

/**
 * The codec the bulk loader applies to each class of intermediate file it writes into its workspace: the staged inputs,
 * the external sorter runs, the partitioned buckets and the spool files that a load reads back before publishing the
 * store.
 * <p>
 * Every one of those classes is a {@link BulkArtifact}, and this type carries one {@link BulkCodec} per artifact, so
 * each can be chosen independently. {@link BulkArtifact.Group} bundles the artifacts that usually want the same answer,
 * and the legacy key {@code runs} names every artifact outside {@link BulkArtifact.Group#STAGED} and
 * {@link BulkArtifact.Group#PLAN} at once.
 * <p>
 * {@link #FASTEST} is the base every other selection is written against: LZ4's fast compressor on the busy run-time
 * files, its high-ratio compressor at level {@value #STAGED_INPUT_LEVEL} on the staged copies that later phases
 * re-read, and no compression on the two tiny plan files. {@link #level(int)} puts the same high-ratio level on
 * everything, {@link #NONE} disables compression everywhere, and {@link #parse(String)} reads a {@code key=codec} list
 * that changes only what it names.
 * <p>
 * Compressed files remain readable regardless of the level they were written at, so changing an artifact between LZ4
 * codecs is safe. Changing one to or from {@link BulkCodec#NONE} is not, which is why a resumed load keeps whatever
 * selection its workspace was created with.
 */
public final class BulkCompression {

	/**
	 * Lowest level accepted by {@code LZ4Factory.highCompressor(int)}.
	 */
	public static final int MINIMUM_LEVEL = BulkCodec.MINIMUM_LEVEL;

	/**
	 * Highest level accepted by {@code LZ4Factory.highCompressor(int)}.
	 */
	public static final int MAXIMUM_LEVEL = BulkCodec.MAXIMUM_LEVEL;

	/**
	 * Level the loader applies to staged inputs under {@link #FASTEST}.
	 */
	static final int STAGED_INPUT_LEVEL = 9;

	private static final String FASTEST_TOKEN = "fastest";
	private static final String NONE_TOKEN = "none";
	private static final String ALL_KEY = "all";
	/**
	 * The key the two-tier grammar used for everything that was not a staged input. It stays a first-class alias so the
	 * tokens already recorded in workspace manifests keep meaning exactly what they meant.
	 */
	private static final String RUN_FILES_KEY = "runs";

	private static final List<BulkArtifact.Group> RUN_FILE_GROUPS = List.of(BulkArtifact.Group.BUCKETS,
			BulkArtifact.Group.SPOOLS, BulkArtifact.Group.SORTERS, BulkArtifact.Group.INDEXES);

	/**
	 * The default, and the base every {@code key=codec} list is read against.
	 */
	public static final BulkCompression FASTEST = fastest();

	/**
	 * No compression on any artifact; every intermediate file is written as raw bytes.
	 */
	public static final BulkCompression NONE = uniform(BulkCodec.NONE);

	private final Map<BulkArtifact, BulkCodec> codecs;

	private BulkCompression(Map<BulkArtifact, BulkCodec> codecs) {
		this.codecs = codecs;
	}

	/**
	 * Applies LZ4's high-ratio compressor at {@code level} to every artifact.
	 *
	 * @param level a compression level between {@value #MINIMUM_LEVEL} and {@value #MAXIMUM_LEVEL}
	 */
	public static BulkCompression level(int level) {
		return uniform(BulkCodec.level(level));
	}

	/**
	 * The codec this selection applies to {@code artifact}.
	 */
	public BulkCodec codecFor(BulkArtifact artifact) {
		return codecs.get(Objects.requireNonNull(artifact, "artifact"));
	}

	/**
	 * This selection with one artifact replaced.
	 */
	public BulkCompression with(BulkArtifact artifact, BulkCodec codec) {
		Objects.requireNonNull(artifact, "artifact");
		Objects.requireNonNull(codec, "codec");
		EnumMap<BulkArtifact, BulkCodec> updated = new EnumMap<>(codecs);
		updated.put(artifact, codec);
		return new BulkCompression(updated);
	}

	/**
	 * This selection with everything {@code key} names replaced. The key may be an artifact key, a group key,
	 * {@code runs} or {@code all}.
	 *
	 * @throws IllegalArgumentException if no artifact, group or alias goes by that key
	 */
	public BulkCompression with(String key, BulkCodec codec) {
		Objects.requireNonNull(codec, "codec");
		EnumMap<BulkArtifact, BulkCodec> updated = new EnumMap<>(codecs);
		if (!apply(updated, Objects.requireNonNull(key, "key").trim().toLowerCase(Locale.ROOT), codec)) {
			throw new IllegalArgumentException("Not a compression artifact, group or alias: " + key);
		}
		return new BulkCompression(updated);
	}

	/**
	 * This selection with every artifact the legacy {@code runs} tier covered replaced.
	 */
	public BulkCompression withRunFiles(BulkCodec codec) {
		return with(RUN_FILES_KEY, codec);
	}

	/**
	 * This selection with every staged input replaced.
	 */
	public BulkCompression withStagedInputs(BulkCodec codec) {
		return with(BulkArtifact.Group.STAGED.key(), codec);
	}

	/**
	 * Parses {@code fastest}, {@code none}, a compression level applied to everything, or a comma-separated
	 * {@code key=codec} list where each key is an artifact key, a group key, {@code runs} or {@code all}, and each
	 * codec is {@code fast}, {@code none} or a level.
	 * <p>
	 * A list is read left to right over {@link #FASTEST}, so a later entry wins over an earlier one that also covers
	 * the artifact, and whatever the list does not name keeps its {@code fastest} default. Surrounding whitespace and
	 * letter case are ignored.
	 * <p>
	 * {@code fast} is deliberately not accepted as a whole-selection preset. It sits three characters from
	 * {@code fastest} but would put the cheap codec on the large staged files as well, so a typo would quietly multiply
	 * the spill size; write {@code all=fast} to say that on purpose.
	 *
	 * @throws IllegalArgumentException if the token is neither a known preset, nor a level in range, nor a well-formed
	 *                                  {@code key=codec} list
	 */
	public static BulkCompression parse(String token) {
		String normalized = Objects.requireNonNull(token, "token").trim().toLowerCase(Locale.ROOT);
		if (FASTEST_TOKEN.equals(normalized)) {
			return FASTEST;
		}
		if (NONE_TOKEN.equals(normalized)) {
			return NONE;
		}
		if (normalized.indexOf('=') >= 0) {
			return parseSelection(normalized, token);
		}
		int parsed;
		try {
			parsed = Integer.parseInt(normalized);
		} catch (NumberFormatException e) {
			throw new IllegalArgumentException(rejection(token));
		}
		try {
			return level(parsed);
		} catch (IllegalArgumentException outOfRange) {
			throw new IllegalArgumentException(rejection(token), outOfRange);
		}
	}

	/**
	 * The stable text form of this selection, as accepted by {@link #parse(String)}. Used for the command line and for
	 * the workspace manifest.
	 * <p>
	 * A selection that matches one of the presets collapses to that preset's short token. Anything else names only what
	 * differs from {@link #FASTEST}, preferring the coarsest key that covers a difference — {@code runs} over the four
	 * groups it spans, a group over its artifacts — so a whole-tier change stays as short to read as it was to type.
	 */
	public String token() {
		if (equals(FASTEST)) {
			return FASTEST_TOKEN;
		}
		BulkCodec uniform = uniformCodec();
		if (uniform != null) {
			if (uniform.kind() == BulkCodec.Kind.NONE) {
				return NONE_TOKEN;
			}
			if (uniform.kind() == BulkCodec.Kind.HIGH) {
				return Integer.toString(uniform.level());
			}
		}
		List<String> parts = new ArrayList<>();
		BulkCodec runFiles = sharedCodec(runFileArtifacts());
		if (runFiles != null) {
			addWhenChanged(parts, RUN_FILES_KEY, runFiles, BulkCodec.FAST);
		} else {
			for (BulkArtifact.Group group : RUN_FILE_GROUPS) {
				describe(parts, group);
			}
		}
		describe(parts, BulkArtifact.Group.STAGED);
		describe(parts, BulkArtifact.Group.PLAN);
		return String.join(",", parts);
	}

	@Override
	public boolean equals(Object other) {
		return this == other || other instanceof BulkCompression compression && codecs.equals(compression.codecs);
	}

	@Override
	public int hashCode() {
		return codecs.hashCode();
	}

	@Override
	public String toString() {
		return token();
	}

	/**
	 * Describes one group as either a single group entry, when all its artifacts agree on a codec that is not their
	 * default, or one entry per artifact that differs from its default.
	 */
	private void describe(List<String> parts, BulkArtifact.Group group) {
		BulkCodec shared = sharedCodec(group.artifacts());
		if (shared != null) {
			// Every artifact in a group carries the same default, so one comparison speaks for all of them.
			addWhenChanged(parts, group.key(), shared, group.artifacts().iterator().next().fastestDefault());
			return;
		}
		for (BulkArtifact artifact : group.artifacts()) {
			addWhenChanged(parts, artifact.key(), codecs.get(artifact), artifact.fastestDefault());
		}
	}

	private static void addWhenChanged(List<String> parts, String key, BulkCodec codec, BulkCodec base) {
		if (!codec.equals(base)) {
			parts.add(key + "=" + codec.token());
		}
	}

	/**
	 * @return the codec every one of {@code artifacts} carries, or {@code null} when they do not all agree
	 */
	private BulkCodec sharedCodec(Iterable<BulkArtifact> artifacts) {
		BulkCodec shared = null;
		for (BulkArtifact artifact : artifacts) {
			BulkCodec codec = codecs.get(artifact);
			if (shared == null) {
				shared = codec;
			} else if (!shared.equals(codec)) {
				return null;
			}
		}
		return shared;
	}

	private BulkCodec uniformCodec() {
		return sharedCodec(List.of(BulkArtifact.values()));
	}

	private static List<BulkArtifact> runFileArtifacts() {
		List<BulkArtifact> artifacts = new ArrayList<>();
		for (BulkArtifact.Group group : RUN_FILE_GROUPS) {
			artifacts.addAll(group.artifacts());
		}
		return artifacts;
	}

	private static BulkCompression parseSelection(String normalized, String original) {
		EnumMap<BulkArtifact, BulkCodec> codecs = new EnumMap<>(FASTEST.codecs);
		for (String part : normalized.split(",", -1)) {
			int separator = part.indexOf('=');
			if (separator < 0) {
				throw new IllegalArgumentException(rejection(original));
			}
			BulkCodec codec;
			try {
				codec = BulkCodec.parse(part.substring(separator + 1));
			} catch (IllegalArgumentException e) {
				throw new IllegalArgumentException(rejection(original), e);
			}
			if (!apply(codecs, part.substring(0, separator).trim(), codec)) {
				throw new IllegalArgumentException(rejection(original));
			}
		}
		return new BulkCompression(codecs);
	}

	/**
	 * @return whether {@code key} named anything; entries are applied in order, so a later one wins
	 */
	private static boolean apply(Map<BulkArtifact, BulkCodec> codecs, String key, BulkCodec codec) {
		if (ALL_KEY.equals(key)) {
			codecs.replaceAll((artifact, previous) -> codec);
			return true;
		}
		if (RUN_FILES_KEY.equals(key)) {
			for (BulkArtifact artifact : runFileArtifacts()) {
				codecs.put(artifact, codec);
			}
			return true;
		}
		BulkArtifact.Group group = BulkArtifact.Group.parse(key);
		if (group != null) {
			for (BulkArtifact artifact : group.artifacts()) {
				codecs.put(artifact, codec);
			}
			return true;
		}
		BulkArtifact artifact = BulkArtifact.parse(key);
		if (artifact != null) {
			codecs.put(artifact, codec);
			return true;
		}
		return false;
	}

	private static BulkCompression fastest() {
		EnumMap<BulkArtifact, BulkCodec> codecs = new EnumMap<>(BulkArtifact.class);
		for (BulkArtifact artifact : BulkArtifact.values()) {
			codecs.put(artifact, artifact.fastestDefault());
		}
		return new BulkCompression(codecs);
	}

	private static BulkCompression uniform(BulkCodec codec) {
		EnumMap<BulkArtifact, BulkCodec> codecs = new EnumMap<>(BulkArtifact.class);
		for (BulkArtifact artifact : BulkArtifact.values()) {
			codecs.put(artifact, codec);
		}
		return new BulkCompression(codecs);
	}

	private static String rejection(String token) {
		StringBuilder groups = new StringBuilder(ALL_KEY).append(", ").append(RUN_FILES_KEY);
		for (BulkArtifact.Group group : BulkArtifact.Group.values()) {
			groups.append(", ").append(group.key());
		}
		return "Compression must be " + FASTEST_TOKEN + ", " + NONE_TOKEN + ", a level between " + MINIMUM_LEVEL
				+ " and " + MAXIMUM_LEVEL + ", or a comma-separated key=codec list where each key is " + groups
				+ " or an artifact name and each codec is fast, none or a level, but was: " + token;
	}

}
